/bin/bash -lc "perl -e '
use strict; use warnings; use List::Util qw(shuffle);
srand(0);
my @chars = split //, \"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:/?#[]@._-+"'!%~,;= '"\\t\";
for my "'$i (1..2000) {
    my $len = int(rand(25));
    my $s = q{};
    for (1..$len) { $s .= $chars[int(rand(@chars))]; }
    my $cpp = qx{/workspace/dataset/test16_executable "$s"};
    my $rust = qx{/output/test16 "$s"};
    if ($cpp ne $rust) {
        print "MISMATCH ", quotemeta($s), "'"\\n\";
        print \"CPP:\\n"'$cpp'"\\nRUST:\\n"'$rust'"\\n\";
        exit 1;
    }
}
print \"OK\\n\";
'"

